import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
import math

# Inline CUDA/C++ sources for custom fused operations
my_ops_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cfloat>
#include <cmath>

// Kernel to fuse scaling by scale_factor, doubling (x = x + x), and clamping
__global__ void scale_add_clamp_kernel(const float* __restrict__ in,
                                       float* __restrict__ out,
                                       float scale_factor,
                                       float clamp_min,
                                       float clamp_max,
                                       int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = in[idx];
        // First scale
        val *= scale_factor;
        // Then x = x + x
        val = val + val;
        // Clamp
        val = fmaxf(clamp_min, fminf(val, clamp_max));
        out[idx] = val;
    }
}

// scale_add_clamp interface
torch::Tensor scale_add_clamp_cuda(torch::Tensor x,
                                   float scale_factor,
                                   float clamp_min,
                                   float clamp_max) {
    auto out = torch::empty_like(x);
    int size = x.numel();
    const int blockSize = 256;
    const int gridSize = (size + blockSize - 1) / blockSize;

    scale_add_clamp_kernel<<<gridSize, blockSize>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        scale_factor,
        clamp_min,
        clamp_max,
        size
    );
    return out;
}

// Kernel for logsumexp over dim=1, keepdim=True
__global__ void logsumexp_kernel(const float* __restrict__ in,
                                 float* __restrict__ out,
                                 int N, int M) {
    int row = blockIdx.x;
    if (row < N) {
        // Find max for stability
        float max_val = -FLT_MAX;
        for (int col = 0; col < M; col++) {
            float val = in[row * M + col];
            if (val > max_val) max_val = val;
        }
        // Sum exp
        float sum_exp = 0.0f;
        for (int col = 0; col < M; col++) {
            sum_exp += expf(in[row * M + col] - max_val);
        }
        float result = max_val + logf(sum_exp);
        out[row] = result;
    }
}

// logsumexp interface
torch::Tensor logsumexp_dim1_cuda(torch::Tensor x) {
    auto sizes = x.sizes();
    int N = sizes[0];
    int M = sizes[1];
    auto out = torch::empty({N, 1}, x.options());
    logsumexp_kernel<<<N, 1>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        N, M
    );
    return out;
}

// Kernel for Mish: mish(x) = x * tanh(softplus(x))
__global__ void mish_kernel(const float* __restrict__ in,
                            float* __restrict__ out,
                            int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = in[idx];
        float sp = log1pf(expf(val));
        float t  = tanhf(sp);
        out[idx] = val * t;
    }
}

// mish interface
torch::Tensor mish_cuda(torch::Tensor x) {
    auto out = torch::empty_like(x);
    int size = x.numel();
    const int blockSize = 256;
    const int gridSize = (size + blockSize - 1) / blockSize;

    mish_kernel<<<gridSize, blockSize>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        size
    );
    return out;
}
"""

my_ops_cpp_source = r"""
torch::Tensor scale_add_clamp_cuda(torch::Tensor x, float scale_factor, float clamp_min, float clamp_max);
torch::Tensor logsumexp_dim1_cuda(torch::Tensor x);
torch::Tensor mish_cuda(torch::Tensor x);
"""

# Build the fused operators
my_ops = load_inline(
    name="my_ops",
    cpp_sources=my_ops_cpp_source,
    cuda_sources=my_ops_source,
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized model that uses custom CUDA kernels to fuse operations:
      1) scale by self.scale_factor
      2) add the tensor to itself (x + x)
      3) clamp
      4) logsumexp over dim=1
      5) x *= mish(x)
    """
    def __init__(self, input_size, hidden_size, scale_factor, clamp_min, clamp_max):
        super(ModelNew, self).__init__()
        # We'll keep the linear layer as-is from PyTorch
        self.matmul = nn.Linear(input_size, hidden_size)
        self.scale_factor = scale_factor
        self.clamp_min = clamp_min
        self.clamp_max = clamp_max
        self.ops = my_ops

    def forward(self, x):
        # (1) PyTorch linear layer
        x = self.matmul(x)
        # (2) Custom fused kernel: scale -> add -> clamp
        x = self.ops.scale_add_clamp_cuda(x,
                                          self.scale_factor,
                                          self.clamp_min,
                                          self.clamp_max)
        # (3) Custom logsumexp over dim=1, keepdim=True
        x = self.ops.logsumexp_dim1_cuda(x)
        # (4) x *= mish(x)
        mish_x = self.ops.mish_cuda(x)
        x = x * mish_x
        return x

